/// Get display spells for a spec, ordered by display_order.
pub fn spells_for_spec(spec_id: u32) -> impl Iterator<Item = &'static SpecDisplaySpell> {
    // Binary search for first entry with this spec_id
    let start = SPEC_DISPLAY_SPELLS
        .partition_point(|s| s.spec_id < spec_id);
    SPEC_DISPLAY_SPELLS[start..]
        .iter()
        .take_while(move |s| s.spec_id == spec_id)
}
